(163, 87, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:14:\"Form tư vấn\";s:6:\"sender\";s:40:\"<wordpress@vionistravel.maiatech.com.vn>\";s:9:\"recipient\";s:21:\"maiatech611@gmail.com\";s:4:\"body\";s:2208:\"<div style=\"font-family:Arial,sans-serif;background:#f4f7fb;padding:30px;\"> <div style=\"max-width:650px;margin:auto;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,.08);\"> <!-- HEADER --> <div style=\"background:linear-gradient(135deg,#0ea5e9,#2563eb);padding:30px;text-align:center;color:#fff;\"> <h1 style=\"margin:0;font-size:28px;\">📩 New Message</h1> <p style=\"margin-top:10px;font-size:14px;opacity:.9;\"> You have received a new contact request from the website </p> </div> <!-- BODY --> <div style=\"padding:30px;\"> <!-- CUSTOMER INFO --> <div style=\"margin-bottom:28px;\"> <h2 style=\"font-size:18px;color:#111827;border-left:4px solid #10b981;padding-left:12px;\"> Customer Information </h2> <table width=\"100%\" cellpadding=\"10\" cellspacing=\"0\" style=\"border-collapse:collapse;margin-top:15px;\"> <tr style=\"background:#f9fafb;\"> <td style=\"font-weight:bold;width:180px;\">Full Name</td> <td>[fullname]</td> </tr> <tr> <td style=\"font-weight:bold;\">Phone Number</td> <td>[phone]</td> </tr> <tr style=\"background:#f9fafb;\"> <td style=\"font-weight:bold;\">Email Address</td> <td>[email]</td> </tr> </table> </div> <!-- MESSAGE --> <div style=\"margin-bottom:28px;\"> <h2 style=\"font-size:18px;color:#111827;border-left:4px solid #f59e0b;padding-left:12px;\"> Customer Message </h2> <div style=\"background:#f9fafb;padding:18px;border-radius:10px;margin-top:15px;line-height:1.7;color:#374151;\"> [message] </div> </div> <!-- DETAILS --> <div> <h2 style=\"font-size:18px;color:#111827;border-left:4px solid #ef4444;padding-left:12px;\"> Submission Details </h2> <table width=\"100%\" cellpadding=\"10\" cellspacing=\"0\" style=\"border-collapse:collapse;margin-top:15px;\"> <tr style=\"background:#f9fafb;\"> <td style=\"font-weight:bold;width:180px;\">Submitted Time</td> <td>[_date] [_time]</td> </tr> <tr> <td style=\"font-weight:bold;\">Page URL</td> <td>[_url]</td> </tr> <tr style=\"background:#f9fafb;\"> <td style=\"font-weight:bold;\">IP Address</td> <td>[_remote_ip]</td> </tr> </table> </div> </div> <!-- FOOTER --> <div style=\"background:#111827;padding:22px;text-align:center;color:#d1d5db;font-size:13px;\"> ✈️ VIONIS TRAVEL <br> Website Contact Notification </div> </div> </div>\";s:18:\"additional_headers\";s:0:\"\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:0;}'),
