(4991, 1154, 'google_map', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d476856.7683751249!2d105.65274004999999!3d20.97485195!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3135ab9bd9861ca1%3A0xe7887f7b72ca17a9!2zSMOgIE7hu5lpLCBWaeG7h3QgTmFt!5e0!3m2!1svi!2s!4v1779941380932!5m2!1svi!2s\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>'),
(4992, 1154, '_google_map', 'field_64990730f97e5'),
(4993, 1154, 'tour_time', '20260529'),
(4994, 1154, '_tour_time', 'field_649bf7010d796'),
(4995, 1154, 'schedule_0_title', '8.00- 8.30'),
(4996, 1154, '_schedule_0_title', 'field_6499083f75a8d'),
(4997, 1154, 'schedule_0_content', '<span style=\"font-weight: 400;\">Get picked up by our friendly guide and start to explore Hanoi City</span>'),
(4998, 1154, '_schedule_0_content', 'field_6499084975a8e'),
(4999, 1154, 'schedule_1_title', '08.45'),
(5000, 1154, '_schedule_1_title', 'field_6499083f75a8d'),
(5001, 1154, 'schedule_1_content', '<span style=\"font-weight: 400;\">Arrive at Tran Quoc Pagoda located on Golden Fish IsLand in West Lake. </span><span style=\"font-weight: 400;\">It is the oldest pagoda in Ha Noi built in the 6th century.</span>'),
(5002, 1154, '_schedule_1_content', 'field_6499084975a8e'),
(5003, 1154, 'schedule_2_title', '09.30'),
(5004, 1154, '_schedule_2_title', 'field_6499083f75a8d'),
(5005, 1154, 'schedule_2_content', '<span style=\"font-weight: 400;\">Visit Ho Chi Minh complex, you have a chance to see the embalmed body of Ho Chi Minh then walk around the garden to see 2 houses where he lived &amp; worked from 1954 to 1969. Then visit One Pillar Pagoda where worships the Godess of Mercy – It is the most unique padoga in the world</span>\r\n<ul>\r\n 	<li><span style=\"font-weight: 400;\">Should dress modestly by covering from shoulders to knees when visiting Ho Chi Minh mausoleum, temples, pagodas…</span></li>\r\n 	<li><span style=\"font-weight: 400;\">Ho Chi Minh’s Mausoleum is closed on Mondays and Fridays.</span></li>\r\n 	<li><span style=\"font-weight: 400;\">Ho Chi Minh’s Mausoleum is closed at least 2 months (15</span><span style=\"font-weight: 400;\">th</span><span style=\"font-weight: 400;\"> June -15</span><span style=\"font-weight: 400;\">th</span><span style=\"font-weight: 400;\"> August) for the annual maintaining but still can take picture Mausoleum and visit around that area</span></li>\r\n</ul>'),
(5006, 1154, '_schedule_2_content', 'field_6499084975a8e'),
(5007, 1154, 'schedule_3_title', '11.15'),
(5008, 1154, '_schedule_3_title', 'field_6499083f75a8d'),
(5009, 1154, 'schedule_3_content', '<span style=\"font-weight: 400;\">Visit Vietnam Ethnology Museum to learn about the culture of 54 ethnic groups living in the whole country of Vietnam</span>\r\n\r\n<span style=\"font-weight: 400;\"><em>Special Note:</em> <em>we will visit Women Museum instead of Ethnology Museum closed on Mondays</em></span>'),
(5010, 1154, '_schedule_3_content', 'field_6499084975a8e'),
(5011, 1154, 'schedule_4_title', '12.45'),
(5012, 1154, '_schedule_4_title', 'field_6499083f75a8d'),
(5013, 1154, 'schedule_4_content', '<span style=\"font-weight: 400;\">Have lunch at our restaurant. You have an opportunity to enjoy Vietnamese cuisine </span><span style=\"font-weight: 400;\">with 8 delicious dishes.</span>'),
(5014, 1154, '_schedule_4_content', 'field_6499084975a8e'),
(5015, 1154, 'schedule_5_title', '14.00-14.15'),
(5016, 1154, '_schedule_5_title', 'field_6499083f75a8d'),
(5017, 1154, 'schedule_5_content', '<span style=\"font-weight: 400;\">Continue to visit Temple of Literature – the first university of Vietnam, established in the 11 centuries</span>'),
(5018, 1154, '_schedule_5_content', 'field_6499084975a8e'),
(5019, 1154, 'schedule_6_title', '15.15'),
(5020, 1154, '_schedule_6_title', 'field_6499083f75a8d'),
(5021, 1154, 'schedule_6_content', '<span style=\"font-weight: 400;\">Leave for Hoa Lo Prison Museum which originally used by the French colonists in Indochina for political prisoners, and later by North Vietnam for U.S. prisoners of war during the Vietnam War. During this later period, it was known to American POWs as the Hanoi Hilton</span>'),
(5022, 1154, '_schedule_6_content', 'field_6499084975a8e'),
(5023, 1154, 'schedule_7_title', '16.15 -16.30'),
(5024, 1154, '_schedule_7_title', 'field_6499083f75a8d'),
(5025, 1154, 'schedule_7_content', '<span style=\"font-weight: 400;\">Tour finishes. Back to hotel</span>'),
(5026, 1154, '_schedule_7_content', 'field_6499084975a8e'),
(5027, 1154, 'schedule', '8'),
