(873, 6, '2025-04-17 17:32:40', '2025-04-17 10:32:40', '.tour-outbound {\n    padding: 4.18rem var(--section) 8.81rem;\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\n    display: flex\n;\n    flex-wrap: wrap;\n    justify-content: space-between;\n}\n\n.tour-outbound .tour-outbound__title h2 {\n    color: #fff;\n    margin-bottom: 1.4rem;\n}\n\n.home-introduce .home-introduce__title h1 {\n    margin-bottom: 1.06rem;\n}\n\n.phongvt-title-main h2, .phongvt-title-main h1, .phongvt-title-main h3, .phongvt-title-main-p p {\n    object-position: 50% 50%;\n    color: var(--Color, #023F88);\n    font-size: 2.5rem;\n    font-style: normal;\n    font-weight: 700;\n    line-height: normal;\n    text-transform: uppercase;\n}\n\n.button.btn__primary {\n    height: 2.5rem;\n    min-height: unset;\n    border-radius: 99rem;\n    padding: 0 1.5rem;\n    font-weight: 400;\n    font-size: 1rem;\n    border: 1px solid var(--theme-color);\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\n    box-shadow: none;\n    color: #fff;\n    outline: none;\n    letter-spacing: 0;\n    border: 0;\n    flex-shrink: 0;\n}\n\n.button.btn__primary span,\n.button.btn__secondary span {\n    position: relative;\n    padding-right: 0.7rem;\n}\n\n.button.btn__primary span:after,\n.button.btn__secondary span:after {\n    width: 0.0625rem;\n    height: 1.05906rem;\n    background: rgb(201 167 167 / 20%);\n    position: absolute;\n    content: \"\";\n    right: 0;\n    top: 50%;\n    transform: translateY(-50%);\n}\n\n.button.btn__primary:hover {\n    background: var(--Linear, linear-gradient(90deg, var(--Color-2, #0071BB) 0%, var(--Color-3, #3CB3E6) 100%));\n    box-shadow: var(--34) var(--45) var(--16) 0px rgba(14, 38, 108, 0), var(--22) var(--29) var(--15) 0px rgba(14, 38, 108, .03), var(--12) var(--16) var(--12) 0px rgba(14, 38, 108, .11), var(--5) var(--7) var(--9) 0px rgba(14,