(1492, 6, '2026-06-26 11:14:40', '2026-06-26 04:14:40', '{\n    \"custom_css[flatsome-child]\": {\n        \"value\": \".footer-social{\\n    display:flex;\\n    flex-wrap:wrap;\\n    gap:12px;\\n}\\n\\n.footer-social a{\\n    width:60px;\\n    height:60px;\\n    background:#293028;\\n    border-radius:50%;\\n    display:flex;\\n    justify-content:center;\\n    align-items:center;\\n    text-decoration:none;\\n    transition:.3s;\\n}\\n\\n.footer-social a:hover{\\n    background:#6ab344;\\n    transform:translateY(-3px);\\n}\\n\\n.footer-social img{\\n    width:28px;\\n    height:28px;\\n}\\n\\n.footer-social i{\\n    color:#fff;\\n    font-size:28px;\\n}\\n\\n.html_nav_position_text {\\n    margin-right: 0 !important;\\n}\\n\\n/*css 1/6/2026*/\\n.main-title * {\\n    font-size: clamp(1.75rem, 5vw, 3rem); /* 28px -> 48px */\\n    font-weight: bold;\\n}\\n\\n.mobile {\\n    display: none;\\n}\\n\\n@media (max-width: 767px) {\\n    .mobile {\\n        display: block;\\n    }\\n}\\n\\n.gtranslate-custom {\\n    text-align: right;\\n}\\n\\n.lightbox-content {\\n    padding: 30px 30px 10px 30px !important;\\n}\\n\\n/*css 1/6/2026*/\\n\\n/* Giao di\\u1ec7n GTranslate */\\n.gtranslate-custom select {\\n    background-color: #ffffff;\\n    color: #222;\\n    border: 1px solid #ddd;\\n    border-radius: 8px;\\n    padding: 6px 10px;\\n    font-size: 15px;\\n    box-shadow: 0 1px 4px rgba(0,0,0,0.08);\\n    cursor: pointer;\\n    transition: all 0.3s ease;\\n}\\n\\n/* Hover select */\\n.gtranslate-custom select:hover {\\n    border-color: #0073e6;\\n    background-color: #f0f8ff;\\n}\\n\\n/* Link ng\\u00f4n ng\\u1eef */\\n.gtranslate-custom a {\\n    display: inline-flex;\\n    align-items: center;\\n    text-decoration: none;\\n    padding: 6px 10px;\\n    margin: 5px 3px;\\n    background: #f9f9f9;\\n    color: #333;\\n    border: 1px solid #ddd;\\n    border-radius: 6px;\\n    font-size: 14px;\\n    transition: all 0.3s;\\n}\\n\\n/* Icon c\\u1edd qu\\u1ed1c gia trong link */\\n.gtranslate-custom a img {\\n    width: 20px;\\n    height: 14px;\\n    margin-right: 5px;\\n    object-fit: cover;\\n}\\n\\n/* Hover link */\\n.gtranslate-custom a:hover {\\n    background: #0073e6;\\n    color: #fff;\\n    border-color: #0073e6;\\n}\\n\\n/* Responsive Mobile */\\n@media (max-width: 768px) {\\n    .gtranslate-custom {\\n        display: flex;\\n        justify-content: center; /* C\\u0103n gi\\u1eefa */\\n        align-items: center;\\n        flex-wrap: nowrap; /* Kh\\u00f4ng cho xu\\u1ed1ng h\\u00e0ng */\\n        gap: 5px;\\n    }\\n    .gtranslate-custom a {\\n        flex: 0 0 auto;\\n        padding: 4px 8px;\\n        font-size: 13px;\\n    }\\n    .gtranslate-custom a img {\\n        width: 16px; /* Icon nh\\u1ecf h\\u01a1n */\\n        height: 12px;\\n        margin-right: 3px;\\n    }\\n}\\n\\n.has-hover .bg,\\n.has-hover [class*=image-] img {\\n    transition: filter 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.4s ease;\\n    transform-origin: center center;\\n}\\n\\n/* Khi hover */\\n.has-hover:hover .bg,\\n.has-hover:hover [class*=image-] img {\\n    transform: scale(1.03) rotateZ(0.3deg) translateY(-2px); /* chuy\\u1ec3n \\u0111\\u1ed9ng nh\\u1eb9 l\\u00ean */\\n    filter: brightness(1.2) contrast(1.1) saturate(1.2); /* gi\\u1ea3m \\u0111\\u1ed9 s\\u00e1ng v\\u00e0 b\\u00e3o h\\u00f2a */\\n    box-shadow: 0 0 20px rgba(255, 255, 255, 0.4), \\n                0 0 40px rgba(255, 255, 255, 0.3), \\n                0 0 60px rgba(255, 255, 255, 0.2), \\n                0 5px 10px rgba(0, 0, 0, 0.1); /* b\\u00f3ng \\u0111\\u1ed5 m\\u1ec1m */\\n    opacity: 1;\\n}\\n\\n\\n\\n.box-text a:not(.button),\\n.box-text h4,\\n.box-text h5,\\n.box-text h6 {\\n    line-height: 1.3;\\n    color: rgb(211 27 27);\\n    margin-bottom: .1em;\\n    margin-top: .1em;\\n    transition: color 0.3s ease, transform 0.3s ease;\\n}\\n\\n.box-text a:not(.button):hover,\\n.box-text h4:hover,\\n.box-text h5:hover,\\n.box-text h6:hover {\\n    color: rgb(255, 0, 0);\\n    transform: translateY(-3px);\\n    cursor: pointer;\\n}\\n\\n\\n\\n.home_blog .box-blog-post:hover {\\n    box-shadow: 0 0px 22px #84c8ff;\\n    transform: scale(1.02);\\n    padding: 10px 20px;\\n    text-align: left;\\n}\\n.home_blog .box-blog-post {\\n    box-shadow: 0 0 18px rgba(0, 0, 0, 0.05);\\n    border-radius: 10px; /* Bo g\\u00f3c */\\n    transition: all 0.s ease;\\n}\\n.home_blog .box-blog-post:hover {\\n    box-shadow: 0 0px 5px #84c8ff;\\n    transform: scale(1.02);\\n    padding: 10px 20px;\\n    text-align: left;\\n    border: 1px solid rgba(0, 0, 0, 0.05); /* Gi\\u1eef vi\\u1ec1n khi hover */\\n}\\n\\n\\n.tour-outbound {\\n    padding: 4.18rem var(--section) 8.81rem;\\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\\n    display: flex\\n;\\n    flex-wrap: wrap;\\n    justify-content: space-between;\\n}\\n\\n.tour-outbound .tour-outbound__title h2 {\\n    color: #fff;\\n    font-size: clamp(1.8rem, 5vw, 3.5rem);\\n    font-style: normal;\\n    font-weight: 700;\\n    line-height: 1.2;\\n    text-transform: uppercase;\\n}\\n\\n.home-introduce .home-introduce__title h1 {\\n    margin-bottom: 1.06rem;\\n}\\n\\n.phongvt-title-main h2,\\n.phongvt-title-main h1,\\n.phongvt-title-main h3,\\n.phongvt-title-main-p p {\\n    object-position: 50% 50%;\\n    color: var(--Color, #023F88);\\n    font-size: 3.5rem;\\n    font-style: normal;\\n    font-weight: 700;\\n    line-height: normal;\\n    text-transform: uppercase;\\n}\\n\\n/* Tablet */\\n@media (max-width: 991px) {\\n    .phongvt-title-main h2,\\n    .phongvt-title-main h1,\\n    .phongvt-title-main h3,\\n    .phongvt-title-main-p p {\\n        font-size: 2.5rem;\\n    }\\n}\\n\\n/* Mobile */\\n@media (max-width: 767px) {\\n    .phongvt-title-main h2,\\n    .phongvt-title-main h1,\\n    .phongvt-title-main h3,\\n    .phongvt-title-main-p p {\\n        font-size: 1.8rem;\\n        line-height: 1.3;\\n    }\\n}\\n\\n\\n\\n.tour-outbound {\\n    padding: 4.18rem var(--section) 8.81rem;\\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\\n    display: flex\\n;\\n    flex-wrap: wrap;\\n    justify-content: space-between;\\n}\\n\\n.fix-section {\\n    border-radius: 2.75rem 2.75rem 0rem 0rem;\\n    background: linear-gradient(180deg, #01549D 0%, var(--Color-2, #0071BB) 60.5%);\\n    padding: 4.44rem var(--section) 16.45rem;\\n    overflow: hidden;\\n}\\n\\n\\n.appointment .item label {\\n    font-size: 14px;\\n    font-weight: 500;\\n    position: absolute;\\n    z-index: 1;\\n    background: #fff;\\n    left: 10px;\\n\\n    padding: 0 10px;\\n    display: inline-block;\\n    width: auto;\\n    border-radius: 8px;\\n    color: #333;\\n}\\n.appointment {\\n    background: #fff;\\n    position: relative;\\n    z-index: 1;\\n}\\n\\n\\n#header .header-nav-main>.menu-item>a {\\n    color: #404040;\\n    font-size: 1.1rem;\\n    font-style: normal;\\n\\ttransition: color 0.3s ease;\\n    font-weight: 600;\\n    line-height: 1.35rem;\\n    padding: var(--30) 0;\\n}\\n#header .header-nav-main > .menu-item.current-menu-item > a {\\n    color: #023f88; /* M\\u00e0u xanh d\\u01b0\\u01a1ng */\\n}\\n#header .header-nav-main > .menu-item > a:hover {\\n    color: #023f88; /* M\\u00e0u xanh d\\u01b0\\u01a1ng */\\n}\\n\\n\\n.phongvt-hieu-ung-toa-hinh {\\n    display: block;\\n    position: relative;\\n    overflow: hidden\\n}\\n\\n.phongvt-hieu-ung-toa-hinh:before {\\n    position: absolute;\\n    top: 50%;\\n    left: 50%;\\n    z-index: 2;\\n    display: block;\\n    content: \'\';\\n    width: 0;\\n    height: 0;\\n    background: rgba(255,255,255,0.2);\\n    border-radius: 100%;\\n    opacity: 0;\\n    -webkit-transform: translate(-50%, -50%);\\n    -ms-transform: translate(-50%, -50%);\\n    -o-transform: translate(-50%, -50%);\\n    transform: translate(-50%, -50%)\\n}\\n\\n@media (min-width: 1025px) {\\n    .phongvt-hieu-ung-toa-hinh:hover:before {\\n        -webkit-animation:circle 0.75s;\\n        -ms-animation: circle 0.75s;\\n        -o-animation: circle 0.75s;\\n        animation: circle 0.75s\\n    }\\n}\\n\\n@-ms-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@-o-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@-webkit-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 6,\n        \"date_modified_gmt\": \"2026-06-26 04:14:40\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '550ab2f3-95fd-4c05-8cca-c9bd438a23b2', '', '', '2026-06-26 11:14:40', '2026-06-26 04:14:40', '', 0, 'http://localhost/vionis/?p=1492', 0, 'customize_changeset', '', 0),
(1493, 6, '2026-06-26 11:14:40', '2026-06-26 04:14:40', '.footer-social{\n    display:flex;\n    flex-wrap:wrap;\n    gap:12px;\n}\n\n.footer-social a{\n    width:60px;\n    height:60px;\n    background:#293028;\n    border-radius:50%;\n    display:flex;\n    justify-content:center;\n    align-items:center;\n    text-decoration:none;\n    transition:.3s;\n}\n\n.footer-social a:hover{\n    background:#6ab344;\n    transform:translateY(-3px);\n}\n\n.footer-social img{\n    width:28px;\n    height:28px;\n}\n\n.footer-social i{\n    color:#fff;\n    font-size:28px;\n}\n\n.html_nav_position_text {\n    margin-right: 0 !important;\n}\n\n/*css 1/6/2026*/\n.main-title * {\n    font-size: clamp(1.75rem, 5vw, 3rem); /* 28px -> 48px */\n    font-weight: bold;\n}\n\n.mobile {\n    display: none;\n}\n\n@media (max-width: 767px) {\n    .mobile {\n        display: block;\n    }\n}\n\n.gtranslate-custom {\n    text-align: right;\n}\n\n.lightbox-content {\n    padding: 30px 30px 10px 30px !important;\n}\n\n/*css 1/6/2026*/\n\n/* Giao diện GTranslate */\n.gtranslate-custom select {\n    background-color: #ffffff;\n    color: #222;\n    border: 1px solid #ddd;\n    border-radius: 8px;\n    padding: 6px 10px;\n    font-size: 15px;\n    box-shadow: 0 1px 4px rgba(0,0,0,0.08);\n    cursor: pointer;\n    transition: all 0.3s ease;\n}\n\n/* Hover select */\n.gtranslate-custom select:hover {\n    border-color: #0073e6;\n    background-color: #f0f8ff;\n}\n\n/* Link ngôn ngữ */\n.gtranslate-custom a {\n    display: inline-flex;\n    align-items: center;\n    text-decoration: none;\n    padding: 6px 10px;\n    margin: 5px 3px;\n    background: #f9f9f9;\n    color: #333;\n    border: 1px solid #ddd;\n    border-radius: 6px;\n    font-size: 14px;\n    transition: all 0.3s;\n}\n\n/* Icon cờ quốc gia trong link */\n.gtranslate-custom a img {\n    width: 20px;\n    height: 14px;\n    margin-right: 5px;\n    object-fit: cover;\n}\n\n/* Hover link */\n.gtranslate-custom a:hover {\n    background: #0073e6;\n    color: #fff;\n    border-color: #0073e6;\n}\n\n/* Responsive Mobile */\n@media (max-width: 768px) {\n    .gtranslate-custom {\n        display: flex;\n        justify-content: center; /* Căn giữa */\n        align-items: center;\n        flex-wrap: nowrap; /* Không cho xuống hàng */\n        gap: 5px;\n    }\n    .gtranslate-custom a {\n        flex: 0 0 auto;\n        padding: 4px 8px;\n        font-size: 13px;\n    }\n    .gtranslate-custom a img {\n        width: 16px; /* Icon nhỏ hơn */\n        height: 12px;\n        margin-right: 3px;\n    }\n}\n\n.has-hover .bg,\n.has-hover [class*=image-] img {\n    transition: filter 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.4s ease;\n    transform-origin: center center;\n}\n\n/* Khi hover */\n.has-hover:hover .bg,\n.has-hover:hover [class*=image-] img {\n    transform: scale(1.03) rotateZ(0.3deg) translateY(-2px); /* chuyển động nhẹ lên */\n    filter: brightness(1.2) contrast(1.1) saturate(1.2); /* giảm độ sáng và bão hòa */\n    box-shadow: 0 0 20px rgba(255, 255, 255, 0.4), \n                0 0 40px rgba(255, 255, 255, 0.3), \n                0 0 60px rgba(255, 255, 255, 0.2), \n                0 5px 10px rgba(0, 0, 0, 0.1); /* bóng đổ mềm */\n    opacity: 1;\n}\n\n\n\n.box-text a:not(.button),\n.box-text h4,\n.box-text h5,\n.box-text h6 {\n    line-height: 1.3;\n    color: rgb(211 27 27);\n    margin-bottom: .1em;\n    margin-top: .1em;\n    transition: color 0.3s ease, transform 0.3s ease;\n}\n\n.box-text a:not(.button):hover,\n.box-text h4:hover,\n.box-text h5:hover,\n.box-text h6:hover {\n    color: rgb(255, 0, 0);\n    transform: translateY(-3px);\n    cursor: pointer;\n}\n\n\n\n.home_blog .box-blog-post:hover {\n    box-shadow: 0 0px 22px #84c8ff;\n    transform: scale(1.02);\n    padding: 10px 20px;\n    text-align: left;\n}\n.home_blog .box-blog-post {\n    box-shadow: 0 0 18px rgba(0, 0, 0, 0.05);\n    border-radius: 10px; /* Bo góc */\n    transition: all 0.s ease;\n}\n.home_blog .box-blog-post:hover {\n    box-shadow: 0 0px 5px #84c8ff;\n    transform: scale(1.02);\n    padding: 10px 20px;\n    text-align: left;\n    border: 1px solid rgba(0, 0, 0, 0.05); /* Giữ viền khi hover */\n}\n\n\n.tour-outbound {\n    padding: 4.18rem var(--section) 8.81rem;\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\n    display: flex\n;\n    flex-wrap: wrap;\n    justify-content: space-between;\n}\n\n.tour-outbound .tour-outbound__title h2 {\n    color: #fff;\n    font-size: clamp(1.8rem, 5vw, 3.5rem);\n    font-style: normal;\n    font-weight: 700;\n    line-height: 1.2;\n    text-transform: uppercase;\n}\n\n.home-introduce .home-introduce__title h1 {\n    margin-bottom: 1.06rem;\n}\n\n.phongvt-title-main h2,\n.phongvt-title-main h1,\n.phongvt-title-main h3,\n.phongvt-title-main-p p {\n    object-position: 50% 50%;\n    color: var(--Color, #023F88);\n    font-size: 3.5rem;\n    font-style: normal;\n    font-weight: 700;\n    line-height: normal;\n    text-transform: uppercase;\n}\n\n/* Tablet */\n@media (max-width: 991px) {\n    .phongvt-title-main h2,\n    .phongvt-title-main h1,\n    .phongvt-title-main h3,\n    .phongvt-title-main-p p {\n        font-size: 2.5rem;\n    }\n}\n\n/* Mobile */\n@media (max-width: 767px) {\n    .phongvt-title-main h2,\n    .phongvt-title-main h1,\n    .phongvt-title-main h3,\n    .phongvt-title-main-p p {\n        font-size: 1.8rem;\n        line-height: 1.3;\n    }\n}\n\n\n\n.tour-outbound {\n    padding: 4.18rem var(--section) 8.81rem;\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\n    display: flex\n;\n    flex-wrap: wrap;\n    justify-content: space-between;\n}\n\n.fix-section {\n    border-radius: 2.75rem 2.75rem 0rem 0rem;\n    background: linear-gradient(180deg, #01549D 0%, var(--Color-2, #0071BB) 60.5%);\n    padding: 4.44rem var(--section) 16.45rem;\n    overflow: hidden;\n}\n\n\n.appointment .item label {\n    font-size: 14px;\n    font-weight: 500;\n    position: absolute;\n    z-index: 1;\n    background: #fff;\n    left: 10px;\n\n    padding: 0 10px;\n    display: inline-block;\n    width: auto;\n    border-radius: 8px;\n    color: #333;\n}\n.appointment {\n    background: #fff;\n    position: relative;\n    z-index: 1;\n}\n\n\n#header .header-nav-main>.menu-item>a {\n    color: #404040;\n    font-size: 1.1rem;\n    font-style: normal;\n	transition: color 0.3s ease;\n    font-weight: 600;\n    line-height: 1.35rem;\n    padding: var(--30) 0;\n}\n#header .header-nav-main > .menu-item.current-menu-item > a {\n    color: #023f88; /* Màu xanh dương */\n}\n#header .header-nav-main > .menu-item > a:hover {\n    color: #023f88; /* Màu xanh dương */\n}\n\n\n.phongvt-hieu-ung-toa-hinh {\n    display: block;\n    position: relative;\n    overflow: hidden\n}\n\n.phongvt-hieu-ung-toa-hinh:before {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    z-index: 2;\n    display: block;\n    content: \'\';\n    width: 0;\n    height: 0;\n    background: rgba(255,255,255,0.2);\n    border-radius: 100%;\n    opacity: 0;\n    -webkit-transform: translate(-50%, -50%);\n    -ms-transform: translate(-50%, -50%);\n    -o-transform: translate(-50%, -50%);\n    transform: translate(-50%, -50%)\n}\n\n@media (min-width: 1025px) {\n    .phongvt-hieu-ung-toa-hinh:hover:before {\n        -webkit-animation:circle 0.75s;\n        -ms-animation: circle 0.75s;\n        -o-animation: circle 0.75s;\n        animation: circle 0.75s\n    }\n}\n\n@-ms-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@-o-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@-webkit-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}', 'flatsome-child', '', 'inherit', 'closed', 'closed', '', '852-revision-v1', '', '', '2026-06-26 11:14:40', '2026-06-26 04:14:40', '', 852, 'http://localhost/vionis/?p=1493', 0, 'revision', '', 0),
