(1517, 6, '2026-06-26 11:33:01', '2026-06-26 04:33:01', '{\n    \"custom_css[flatsome-child]\": {\n        \"value\": \".footer-social{\\n    display:flex;\\n    gap:10px;\\n    align-items:center;\\n    flex-wrap:wrap;\\n}\\n\\n.footer-social a{\\n    width:40px;\\n    height:40px;\\n    border-radius:50%;\\n    background:#2b322d;\\n    color:#fff;\\n    display:flex;\\n    align-items:center;\\n    justify-content:center;\\n    text-decoration:none;\\n    transition:all .3s ease;\\n}\\n\\n.footer-social a:hover{\\n    background:#80C342;\\n    transform:translateY(-2px);\\n}\\n\\n.footer-social a i{\\n    font-size:18px;\\n    line-height:1;\\n}\\n\\n.footer-social a img{\\n    width:22px;\\n    height:22px;\\n    object-fit:contain;\\n    display:block;\\n}\\n\\n.html_nav_position_text {\\n    margin-right: 0 !important;\\n}\\n\\n/*css 1/6/2026*/\\n.main-title * {\\n    font-size: clamp(1.75rem, 5vw, 3rem); /* 28px -> 48px */\\n    font-weight: bold;\\n}\\n\\n.mobile {\\n    display: none;\\n}\\n\\n@media (max-width: 767px) {\\n    .mobile {\\n        display: block;\\n    }\\n}\\n\\n.gtranslate-custom {\\n    text-align: right;\\n}\\n\\n.lightbox-content {\\n    padding: 30px 30px 10px 30px !important;\\n}\\n\\n/*css 1/6/2026*/\\n\\n/* Giao di\\u1ec7n GTranslate */\\n.gtranslate-custom select {\\n    background-color: #ffffff;\\n    color: #222;\\n    border: 1px solid #ddd;\\n    border-radius: 8px;\\n    padding: 6px 10px;\\n    font-size: 15px;\\n    box-shadow: 0 1px 4px rgba(0,0,0,0.08);\\n    cursor: pointer;\\n    transition: all 0.3s ease;\\n}\\n\\n/* Hover select */\\n.gtranslate-custom select:hover {\\n    border-color: #0073e6;\\n    background-color: #f0f8ff;\\n}\\n\\n/* Link ng\\u00f4n ng\\u1eef */\\n.gtranslate-custom a {\\n    display: inline-flex;\\n    align-items: center;\\n    text-decoration: none;\\n    padding: 6px 10px;\\n    margin: 5px 3px;\\n    background: #f9f9f9;\\n    color: #333;\\n    border: 1px solid #ddd;\\n    border-radius: 6px;\\n    font-size: 14px;\\n    transition: all 0.3s;\\n}\\n\\n/* Icon c\\u1edd qu\\u1ed1c gia trong link */\\n.gtranslate-custom a img {\\n    width: 20px;\\n    height: 14px;\\n    margin-right: 5px;\\n    object-fit: cover;\\n}\\n\\n/* Hover link */\\n.gtranslate-custom a:hover {\\n    background: #0073e6;\\n    color: #fff;\\n    border-color: #0073e6;\\n}\\n\\n/* Responsive Mobile */\\n@media (max-width: 768px) {\\n    .gtranslate-custom {\\n        display: flex;\\n        justify-content: center; /* C\\u0103n gi\\u1eefa */\\n        align-items: center;\\n        flex-wrap: nowrap; /* Kh\\u00f4ng cho xu\\u1ed1ng h\\u00e0ng */\\n        gap: 5px;\\n    }\\n    .gtranslate-custom a {\\n        flex: 0 0 auto;\\n        padding: 4px 8px;\\n        font-size: 13px;\\n    }\\n    .gtranslate-custom a img {\\n        width: 16px; /* Icon nh\\u1ecf h\\u01a1n */\\n        height: 12px;\\n        margin-right: 3px;\\n    }\\n}\\n\\n.has-hover .bg,\\n.has-hover [class*=image-] img {\\n    transition: filter 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.4s ease;\\n    transform-origin: center center;\\n}\\n\\n/* Khi hover */\\n.has-hover:hover .bg,\\n.has-hover:hover [class*=image-] img {\\n    transform: scale(1.03) rotateZ(0.3deg) translateY(-2px); /* chuy\\u1ec3n \\u0111\\u1ed9ng nh\\u1eb9 l\\u00ean */\\n    filter: brightness(1.2) contrast(1.1) saturate(1.2); /* gi\\u1ea3m \\u0111\\u1ed9 s\\u00e1ng v\\u00e0 b\\u00e3o h\\u00f2a */\\n    box-shadow: 0 0 20px rgba(255, 255, 255, 0.4), \\n                0 0 40px rgba(255, 255, 255, 0.3), \\n                0 0 60px rgba(255, 255, 255, 0.2), \\n                0 5px 10px rgba(0, 0, 0, 0.1); /* b\\u00f3ng \\u0111\\u1ed5 m\\u1ec1m */\\n    opacity: 1;\\n}\\n\\n\\n\\n.box-text a:not(.button),\\n.box-text h4,\\n.box-text h5,\\n.box-text h6 {\\n    line-height: 1.3;\\n    color: rgb(211 27 27);\\n    margin-bottom: .1em;\\n    margin-top: .1em;\\n    transition: color 0.3s ease, transform 0.3s ease;\\n}\\